// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ContestRatingRun) predicate.ContestRatingRun {
	return predicate.ContestRatingRun(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ContestRatingRun) predicate.ContestRatingRun {
	return predicate.ContestRatingRun(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ContestRatingRun) predicate.ContestRatingRun {
	return predicate.ContestRatingRun(sql.NotPredicates(p))
}
